// Transferred from continuity-protection.js so 800 V protection follows the architecture.
const label=(x,y,t,small=false)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${small?17:23}" fill="var(--ink)">${t}</text>`;
export function renderDCProtection(compact=false) {
 if(compact) return `<div class="dc-protection"><svg viewBox="0 0 380 620" role="img" aria-label="800 volt rectifier and bus capacitor feed a cable and DC breaker before the rack feeder fault."><rect x="110" y="15" width="180" height="75" rx="9" fill="var(--panel)"/>${label(200,45,'Rectifier')}${label(200,75,'800 V DC',true)}<path d="M290 52h50v90m0 0c-35 0-35 22 0 22c-35 0-35 22 0 22c-35 0-35 22 0 22v53m0 76v178h-50M110 52H40v463h70M40 112h135m25 0h140" fill="none" stroke="var(--teal)" stroke-width="4"/><path d="M176 94v36m23-36v36" stroke="var(--teal)" stroke-width="5"/>${label(182,161,'Bus capacitor',true)}${label(193,219,'Cable inductance',true)}<rect x="240" y="261" width="134" height="76" rx="10" fill="var(--surface)" stroke="var(--amber)" stroke-width="3"/>${label(307,292,'DC breaker',true)}${label(307,321,'Arc chamber',true)}<path d="M340 397H225l-15-13-15 26-15-13H40" stroke="var(--amber)" stroke-width="4" fill="none"/>${label(192,438,'Feeder short circuit',true)}<rect x="110" y="478" width="180" height="75" rx="9" fill="var(--panel)"/>${label(200,509,'Rack')}${label(200,538,'converters',true)}</svg><div class="dc-protection-facts"><span><strong>DC voltage rating</strong>Withstand the open-circuit voltage</span><span><strong>Interrupting rating</strong>Clear the available fault current</span><span><strong>Stored energy</strong>Handle energy released during clearing</span></div></div>`;

 return `<div class="dc-protection"><svg viewBox="0 0 1100 400" role="img" aria-label="An 800 volt rectifier and charged bus capacitor feed a branch. Cable inductance stores magnetic energy. The DC breaker must interrupt current and manage that stored energy."><rect x="20" y="90" width="170" height="145" rx="12" fill="var(--panel)"/><rect x="880" y="90" width="185" height="145" rx="12" fill="var(--panel)"/>${label(105,145,'Rectifier')}${label(105,179,'800 V DC')}${label(972,150,'Rack')}${label(972,183,'converters',true)}<path d="M190 125H360m0 0c0-45 25-45 25 0c0-45 25-45 25 0c0-45 25-45 25 0c0-45 25-45 25 0H580M740 125H880M972 235v100H105V235M275 125v78M275 230v105" stroke="var(--teal)" stroke-width="5" fill="none"/><path d="M250 204h50M250 228h50" stroke="var(--teal)" stroke-width="6"/><path d="M818 125v78l-13 14 26 15-26 15 13 14v74" stroke="var(--amber)" stroke-width="4" fill="none"/>${label(715,290,'Short circuit',true)}<rect x="580" y="78" width="160" height="100" rx="10" fill="var(--surface)" stroke="var(--amber)" stroke-width="3"/>${label(660,120,'DC breaker')}${label(660,150,'+ arc chamber',true)}${label(414,60,'Cable inductance',true)}${label(200,280,'Capacitor',true)}</svg><div class="dc-protection-facts"><span><strong>DC voltage rating</strong>Withstand the open-circuit voltage</span><span><strong>Interrupting rating</strong>Clear the available fault current</span><span><strong>Stored energy</strong>Handle energy released during clearing</span></div></div>`;
}
